-- VFDA VA Quiz App - Phase 2c database changes (rule tiers, doctor setup flow).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after phase2b.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261029170000_rule_tiers.sql =====

-- Phase 2c: rule tiers and the doctor's 3-step setup (settings.doctor_flow).
--
--   profile  the 8 office setup questions the doctor answers (step 1)
--   doctor   rules from the doctor's card PDFs, confirmed per card group (step 2)
--   default  VFDA standards: accepted automatically as source vfda_default (step 3)
--   auto     filled from setup answers (or by VFDA); never shown to the doctor
--
-- Every office always has a row for each default-tier and auto-tier rule:
-- created when the office is created, kept up to date when setup answers
-- change, and back-filled by `npm run import:bank` (refresh_all_office_rules).
-- Safe to run more than once.

-- ---------------------------------------------------------------------------
-- Rule slots: tier, auto_rule, card_group.
-- ---------------------------------------------------------------------------
alter table public.rule_slots add column if not exists tier text not null default 'doctor';
alter table public.rule_slots add column if not exists auto_rule text;
alter table public.rule_slots add column if not exists card_group text;
alter table public.rule_slots drop constraint if exists rule_slots_tier_check;
alter table public.rule_slots add constraint rule_slots_tier_check
  check (tier in ('profile', 'auto', 'default', 'doctor'));
create index if not exists rule_slots_tier_idx on public.rule_slots (tier);

-- Office rules gain one more source: 'auto' (filled by the app).
alter table public.office_rules drop constraint if exists office_rules_source_check;
alter table public.office_rules add constraint office_rules_source_check
  check (source in ('card_import', 'doctor', 'vfda_default', 'vfda', 'auto'));

-- ---------------------------------------------------------------------------
-- Doctors never see auto-tier slots; they need the card groups and flow.
-- ---------------------------------------------------------------------------
drop policy if exists "doctor reads rule slots" on public.rule_slots;
create policy "doctor reads rule slots" on public.rule_slots
  for select to authenticated
  using ((select private.my_role()) = 'doctor' and tier <> 'auto');

drop policy if exists "doctor reads setup settings" on public.settings;
create policy "doctor reads setup settings" on public.settings
  for select to authenticated
  using ((select private.my_role()) = 'doctor'
         and key in ('conditions', 'gray_card_questions', 'office_fields', 'gray_card_workflow_fields',
                     'card_groups', 'card_group_order', 'doctor_flow'));

-- ---------------------------------------------------------------------------
-- Doctor writes: as before, always the doctor's own accepted answer, except
-- that a doctor may turn down a card proposal (status 'rejected'), and may not
-- write auto-tier rules. Writes made by refresh_office_rules() (flagged with
-- vfda.system_write) are the app's own and pass through.
-- ---------------------------------------------------------------------------
create or replace function private.guard_office_rule()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null
     or private.is_admin()
     or coalesce(current_setting('vfda.system_write', true), '') = 'on' then
    return new;
  end if;
  if exists (select 1 from public.rule_slots s where s.key = new.rule_slot_key and s.tier = 'auto') then
    raise exception 'This rule is filled automatically.' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' then
    new.office_id          := old.office_id;
    new.rule_slot_key      := old.rule_slot_key;
    new.source_document_id := old.source_document_id;
    new.source_quote       := old.source_quote;
    new.vfda_reviewed_by   := old.vfda_reviewed_by;
    new.vfda_reviewed_at   := old.vfda_reviewed_at;
    if new.rule is distinct from old.rule or new.attachments is distinct from old.attachments then
      new.source := 'doctor';
    else
      new.source := old.source;
    end if;
    if new.status = 'rejected' and old.source = 'card_import' and new.source = 'card_import' then
      new.doctor_approved_by := null;
      new.doctor_approved_at := null;
      return new;
    end if;
  else
    new.source             := 'doctor';
    new.source_document_id := null;
    new.source_quote       := null;
    new.vfda_reviewed_by   := null;
    new.vfda_reviewed_at   := null;
  end if;
  new.status             := 'accepted';
  new.doctor_approved_by := (select auth.uid());
  new.doctor_approved_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Auto-tier values. APPROVED_TOOLS is saved as "Label: tool" lines (the setup
-- form has one box per label), e.g. "EHR: ChiroTouch", "Remote access: none".
-- Returns null when there's nothing to fill yet (or VFDA fills it by hand).
-- ---------------------------------------------------------------------------
create or replace function private.auto_rule_value(p_key text, p_office_name text, p_doctor text, p_tools jsonb)
returns jsonb
language plpgsql
immutable
set search_path = ''
as $$
declare
  pattern         text;
  none_if_missing boolean := false;
  tool            text;
begin
  case p_key
    when 'CLINIC_NAME' then return to_jsonb(nullif(btrim(p_office_name), ''));
    when 'DOCTOR_NAME' then return to_jsonb(nullif(btrim(p_doctor), ''));
    when 'EHR_NAME' then pattern := '^(ehr|emr)';
    when 'TEXT_PLATFORM' then pattern := '^(text|sms)';
    when 'VOIP_PLATFORM' then pattern := '^(phone|voip)';
    when 'EMAIL_PLATFORM' then pattern := '^e-?mail';
    when 'IMAGING_SYSTEM' then pattern := '^(imaging|x-?ray)'; none_if_missing := true;
    when 'REMOTE_ACCESS_TOOL' then pattern := '^remote'; none_if_missing := true;
    else return null;  -- training links: VFDA fills from its vendor list
  end case;

  if p_tools is null or jsonb_typeof(p_tools) <> 'array' then
    return null;
  end if;
  select btrim(substring(e from position(':' in e) + 1)) into tool
  from jsonb_array_elements_text(p_tools) e
  where position(':' in e) > 0
    and lower(btrim(split_part(e, ':', 1))) ~ pattern
    and btrim(substring(e from position(':' in e) + 1)) <> ''
  limit 1;
  if tool is not null then
    return to_jsonb(tool);
  end if;
  -- "none if not listed", once the doctor has listed their tools
  if none_if_missing and exists (
    select 1 from jsonb_array_elements_text(p_tools) e where btrim(e) <> ''
  ) then
    return '"none"'::jsonb;
  end if;
  return null;
end;
$$;

-- Creates any missing default-tier rules (accepted, vfda_default) and fills
-- auto-tier rules. Never touches a rule someone has edited: defaults are
-- updated only while untouched (source vfda_default, not yet confirmed by
-- the doctor), auto rules only while source is 'auto'.
create or replace function private.refresh_office_rules(p_office_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  o      public.offices;
  tools  jsonb;
  doctor text;
  s      record;
  v      jsonb;
  prev   text := coalesce(current_setting('vfda.system_write', true), '');
begin
  select * into o from public.offices where id = p_office_id;
  if not found then
    return;
  end if;
  perform set_config('vfda.system_write', 'on', true);

  insert into public.office_rules (office_id, rule_slot_key, rule, source, status, workflows)
  select o.id, rs.key, rs.default_answer, 'vfda_default', 'accepted', rs.workflows
  from public.rule_slots rs
  where rs.tier = 'default'
  on conflict (office_id, rule_slot_key, source_document_id) do nothing;

  update public.office_rules r
  set rule = rs.default_answer
  from public.rule_slots rs
  where r.office_id = o.id
    and r.rule_slot_key = rs.key
    and rs.tier = 'default'
    and r.source_document_id is null
    and r.source = 'vfda_default'
    and r.doctor_approved_at is null
    and r.rule is distinct from rs.default_answer;

  select r.rule into tools
  from public.office_rules r
  where r.office_id = o.id and r.rule_slot_key = 'APPROVED_TOOLS' and r.source_document_id is null;
  doctor := coalesce(
    nullif(btrim(o.doctor_name), ''),
    (select nullif(btrim(p.full_name), '') from public.profiles p
     where p.office_id = o.id and p.role = 'doctor' order by p.created_at limit 1));

  for s in select rs.key, rs.workflows from public.rule_slots rs where rs.tier = 'auto' order by rs.position loop
    v := private.auto_rule_value(s.key, o.name, doctor, tools);
    insert into public.office_rules (office_id, rule_slot_key, rule, source, status, workflows)
    values (o.id, s.key, v, 'auto', case when v is null then 'proposed' else 'accepted' end, s.workflows)
    on conflict (office_id, rule_slot_key, source_document_id) do update
      set rule = excluded.rule, status = excluded.status
      where public.office_rules.source = 'auto'
        and public.office_rules.rule is distinct from excluded.rule;
  end loop;

  perform set_config('vfda.system_write', prev, true);
end;
$$;

create or replace function private.refresh_office_rules_trigger()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_table_name = 'offices' then
    perform private.refresh_office_rules(new.id);
  else
    perform private.refresh_office_rules(coalesce(new.office_id, old.office_id));
  end if;
  return null;
end;
$$;

drop trigger if exists refresh_rules_on_create on public.offices;
create trigger refresh_rules_on_create
  after insert on public.offices
  for each row execute function private.refresh_office_rules_trigger();

drop trigger if exists refresh_rules_on_rename on public.offices;
create trigger refresh_rules_on_rename
  after update of name, doctor_name on public.offices
  for each row
  when (old.name is distinct from new.name or old.doctor_name is distinct from new.doctor_name)
  execute function private.refresh_office_rules_trigger();

drop trigger if exists refresh_rules_on_tools on public.office_rules;
create trigger refresh_rules_on_tools
  after insert or update of rule on public.office_rules
  for each row
  when (new.rule_slot_key = 'APPROVED_TOOLS' and new.source_document_id is null)
  execute function private.refresh_office_rules_trigger();

drop trigger if exists refresh_rules_on_tools_delete on public.office_rules;
create trigger refresh_rules_on_tools_delete
  after delete on public.office_rules
  for each row
  when (old.rule_slot_key = 'APPROVED_TOOLS' and old.source_document_id is null)
  execute function private.refresh_office_rules_trigger();

grant execute on all functions in schema private to authenticated;

-- For the import script (service role only): back-fill every office after
-- new or changed rule slots arrive. Returns the number of offices.
create or replace function public.refresh_all_office_rules()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  o record;
  n integer := 0;
begin
  for o in select id from public.offices loop
    perform private.refresh_office_rules(o.id);
    n := n + 1;
  end loop;
  return n;
end;
$$;

revoke all on function public.refresh_all_office_rules() from public, anon, authenticated;
grant execute on function public.refresh_all_office_rules() to service_role;

commit;
